UPDATE crm09_contact
   SET crm09_contact_nm         = #{req.contactName}
     , crm09_item_type_cd       = #{req.itemTypeCode}
     , crm09_contact_emp_nm     = #{req.contactEmpName}
     , crm09_contact_org_nm     = #{req.contactOrgName}
     , crm09_contact_title      = #{req.contactTitle}
     , crm09_contact_pos        = #{req.contactPos}
     , crm09_contact_tel_no     = #{req.contactTelNo}
     , crm09_contact_mobile_no  = #{req.contactMobileNo}
     , crm09_contact_email_addr = #{req.contactEmailAddr}
     , crm09_major_issues       = #{req.majorIssues}
     , crm09_note               = #{req.note}
 WHERE crm09_contact_id = #{req.contactId}
   AND crm09_company_id = #{companyId}
